/* ───────────── 9. 실전 총정리 ───────────── */
function strategyBody() {
  const parts = [["b1", "생명과학의 이해", "01-life.html"], ["b2", "사람의 물질대사", "02-metabolism.html"], ["b3", "자극의 전달과 근수축", "03-neuron-muscle.html"], ["b4", "신경계와 항상성", "04-nervous-homeostasis.html"], ["b5", "방어 작용", "05-defense.html"], ["b6", "유전 정보와 세포 분열", "06-cell-division.html"], ["b7", "사람의 유전", "07-human-genetics.html"], ["b8", "생태계와 상호 작용", "08-ecosystem.html"]];
  const rows = parts.map(([id, name, file]) => {
    const s = partStats("bio1", id);
    return [`<a href="${file}">${name}</a>`, s.avg, `${s.avgPts}점`, `${s.min}~${s.max}`];
  });
  return `<h2>시험 뼈대</h2>
<p>생명과학Ⅰ은 <strong>20문항 50점, 30분</strong>입니다. 2점 10개와 3점 10개로 구성되고(최근 ${EXAMS.length}회 모두 동일), 3점 문항은 앞 10문항에 평균 3.9개, 뒤 10문항에 평균 6.1개로 <em>뒤쪽에 더 몰려</em> 있습니다. 앞부분은 개념 문항(빠르게), 뒤쪽은 표·가계도·DNA 상대량 문항(시간을 남겨서)으로 나누어 접근합니다.</p>
<h2>파트별 출제 비중</h2>
${tbl(["파트", "회당 문항", "회당 배점", "회차별 범위"], rows)}
<p>표는 최근 ${EXAMS.length}회 실제 시험지의 자동 분류 결과입니다. <strong>유전(6+7) 파트가 회당 약 6문항</strong>으로 가장 크고, 그다음이 생태계·항상성 순입니다. 유전 두 파트만 완성해도 30 %를 확보합니다.</p>
<h2>시간 배분 예시</h2>
${tbl(["구간", "문항", "권장 시간", "요령"], [["앞부분", "1~9번", "약 8분", "개념·자료 해석. 보기별 참/거짓을 짧게 판정"], ["중반", "10~15번", "약 10분", "그래프·표. 호르몬 ㉠, ㉡ 정체 → 방향 → 결론 순"], ["후반", "16~20번", "약 12분", "가계도+DNA 상대량, 비분리. 유전자형 표를 그리며 푼다"]])}
<h2>킬러 유형 정리</h2>
<ul><li><strong>유전 가계도 + DNA 상대량</strong>: 위치 확정 → 우열 → 유전자형(DNA 상대량) → 확률 순서. 파트 7 참고.</li><li><strong>DNA 상대량 + 감수 분열</strong>: 각 세포의 (핵상, 상대량 합)으로 시기를 정하고 유전자형을 추론. 파트 6 참고.</li><li><strong>막전위/전도 표</strong>: 속도 v를 먼저 구하고 각 시점 위치를 계산. 파트 3 참고.</li><li><strong>근수축 길이</strong>: A대 일정, H대 감소량 = 마디 감소량. 파트 3 참고.</li></ul>
<h2>전 파트 핵심 한 줄</h2>
${tbl(["파트", "이것만은"], [["생명과학의 이해", "조작 변인 = 다르게 한 것, 종속 변인 = 달라진 결과"], ["사람의 물질대사", "단백질 → 암모니아 → 간에서 요소, 지방산은 암죽관"], ["자극·근수축", "탈분극 = Na⁺ 유입, 재분극 = K⁺ 유출, A대는 불변"], ["신경계와 항상성", "인슐린↓혈당 / 글루카곤↑혈당, ADH↑ → 오줌량↓"], ["방어 작용", "항체는 형질 세포, 백신은 항원, 2차는 기억 세포"], ["세포 분열", "DNA 상대량 합 4 / 2 / 1 = 복제 후 / G₁ 또는 감수2 / 생식세포"], ["사람의 유전", "정상×정상→환자 = 열성, 딸 환자의 아버지는 환자(X 열성)"], ["생태계", "에너지는 흐르고 물질은 순환, 2차 천이가 빠름"]])}
<h2>함정 문장 TOP 10</h2>
<ol><li>항상성 사례를 적응과 진화로 읽기.</li><li>바이러스가 독립적 물질대사를 한다.</li><li>재분극은 Na⁺ 유입이다.</li><li>근수축에서 A대 길이가 줄어든다.</li><li>교감 신경이 소화를 촉진한다.</li><li>기억 세포가 항체를 분비한다.</li><li>감수 1분열에서 염색 분체가 분리된다.</li><li>정상 부모에서 환자가 나오면 우성이다.</li><li>에너지가 생태계에서 순환한다.</li><li>ADH가 많으면 오줌량이 늘어난다.</li></ol>
<h2>오답 노트 요령</h2>
<p>정답 번호가 아니라 <strong>내가 고른 함정 문장</strong>과 <strong>파트</strong>를 적습니다. 풀어보기에서 틀린 문항은 자동으로 오답 노트에 쌓이고, 채점 결과에 파트별 정답률이 나오므로 약한 파트를 골라 <em>“모아 풀기”</em>로 이어가세요.</p>`;
}
